class Solution:
    def maxLength(self, nums: List[int]) -> int:
        PR = [2, 3, 5, 7]
        def exps(v):
            r = []
            for p in PR:
                e = 0
                while v % p == 0:
                    v //= p
                    e += 1
                r.append(e)
            return r
        n = len(nums)
        E = [exps(v) for v in nums]
        ans = 1
        for i in range(n):
            s = E[i][:]
            mx = E[i][:]
            mn = E[i][:]
            for j in range(i, n):
                if j > i:
                    for t in range(4):
                        s[t] += E[j][t]
                        mx[t] = max(mx[t], E[j][t])
                        mn[t] = min(mn[t], E[j][t])
                if all(s[t] == mx[t] + mn[t] for t in range(4)):
                    ans = max(ans, j - i + 1)
        return ans

