class Solution {
public:
    int maxLength(vector<int>& nums) {
        int pr[4] = {2, 3, 5, 7};
        int n = nums.size();
        vector<array<int,4>> E(n);
        for (int i = 0; i < n; i++) {
            int v = nums[i];
            for (int t = 0; t < 4; t++) {
                int e = 0;
                while (v % pr[t] == 0) { v /= pr[t]; e++; }
                E[i][t] = e;
            }
        }
        int ans = 1;
        for (int i = 0; i < n; i++) {
            array<int,4> s = E[i], mx = E[i], mn = E[i];
            for (int j = i; j < n; j++) {
                if (j > i) {
                    for (int t = 0; t < 4; t++) {
                        s[t] += E[j][t];
                        mx[t] = max(mx[t], E[j][t]);
                        mn[t] = min(mn[t], E[j][t]);
                    }
                }
                bool ok = true;
                for (int t = 0; t < 4; t++) if (s[t] != mx[t] + mn[t]) ok = false;
                if (ok) ans = max(ans, j - i + 1);
            }
        }
        return ans;
    }
};

