class Solution {
    public int maxLength(int[] nums) {
        int[] pr = {2, 3, 5, 7};
        int n = nums.length;
        int[][] E = new int[n][4];
        for (int i = 0; i < n; i++) {
            int v = nums[i];
            for (int t = 0; t < 4; t++) {
                int e = 0;
                while (v % pr[t] == 0) { v /= pr[t]; e++; }
                E[i][t] = e;
            }
        }
        int ans = 1;
        for (int i = 0; i < n; i++) {
            int[] s = E[i].clone(), mx = E[i].clone(), mn = E[i].clone();
            for (int j = i; j < n; j++) {
                if (j > i) {
                    for (int t = 0; t < 4; t++) {
                        s[t] += E[j][t];
                        mx[t] = Math.max(mx[t], E[j][t]);
                        mn[t] = Math.min(mn[t], E[j][t]);
                    }
                }
                boolean ok = true;
                for (int t = 0; t < 4; t++) if (s[t] != mx[t] + mn[t]) ok = false;
                if (ok) ans = Math.max(ans, j - i + 1);
            }
        }
        return ans;
    }
}

