var maxLength = function(nums) {
    const PR = [2, 3, 5, 7];
    const n = nums.length;
    const E = nums.map(v => PR.map(p => {
        let e = 0;
        while (v % p === 0) { v /= p; e++; }
        return e;
    }));
    let ans = 1;
    for (let i = 0; i < n; i++) {
        const s = [...E[i]], mx = [...E[i]], mn = [...E[i]];
        for (let j = i; j < n; j++) {
            if (j > i) {
                for (let t = 0; t < 4; t++) {
                    s[t] += E[j][t];
                    mx[t] = Math.max(mx[t], E[j][t]);
                    mn[t] = Math.min(mn[t], E[j][t]);
                }
            }
            if (s.every((v, t) => v === mx[t] + mn[t])) ans = Math.max(ans, j - i + 1);
        }
    }
    return ans;
};
